<?php
declare(strict_types=1);namespace Essivery\Partner\Controllers;
use Essivery\Api\Core\Auth;use Essivery\Api\Core\Request;use Essivery\Api\Core\Response;use Essivery\Api\Services\AuditService;use Essivery\Partner\Domain\PartnerContext;use Essivery\Partner\Repositories\PartnerRestaurantRepository;use Essivery\Partner\Services\PartnerRestaurantService;use Essivery\Partner\Services\PartnerSetupService;
final class PartnerRestaurantController{public function __construct(private array$c){}public function show(Request$r):never{Response::success($this->service()->get($this->ctx($r)),200,['requestId'=>$r->requestId]);}public function update(Request$r):never{$x=Auth::context($r);$audit=new AuditService($this->pdo());$v=$this->service()->update($this->ctx($r),$r->body,function($m)use($audit,$x,$r){$safe=['cuisineCodes'=>$m['cuisineCodes'],'cuisineCount'=>$m['cuisineCount'],'menuSetupMode'=>$m['menuSetupMode']];$audit->record((int)$x['user_id'],(int)$x['identity_id'],'partner_setup.restaurant_updated','partner_setup_application',null,$r->requestId,$safe);$audit->record((int)$x['user_id'],(int)$x['identity_id'],'partner_setup.restaurant_completed','partner_setup_application',null,$r->requestId,$safe);if($m['modeChanged'])$audit->record((int)$x['user_id'],(int)$x['identity_id'],'partner_setup.restaurant_menu_mode_changed','partner_setup_application',null,$r->requestId,$safe);});Response::success($v,200,['requestId'=>$r->requestId]);}private function service():PartnerRestaurantService{$p=$this->pdo();$d=$this->c['partner']['setup']??require dirname(__DIR__).'/config/setup.php';return new PartnerRestaurantService($p,new PartnerRestaurantRepository($p),new PartnerSetupService($p,$d));}private function ctx(Request$r):PartnerContext{return$r->attributes['partnerContext'];}private function pdo():\PDO{return$this->c['database']->connection();}}
